/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_member_email_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The member who requested email verification. {@link todo_app_members.id}.
