  for (const token of unusedFilter.data) {
    TestValidator.equals(
      "unused filter returns only unused tokens",
      token.used,
      false,
    );
  }
  // Test filter by expired tokens (true)
  const expiredFilter =
    await api.functional.todoApp.member.password_resets.index(
      memberConnection,
