import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

export async function test_api_todo_restore_from_trash_success(
  connection: api.IConnection,
): Promise<void> {
  // Create member connection
  const memberConnection: api.IConnection = { host: connection.host };
  // Register member using utility function
  const authorizedMember = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppMember.IJoin,
  });
  typia.assert(authorizedMember);
  // Create todo with various attributes using utility function
  const createTodoBody: ITodoAppTodo.ICreate = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    start_date: new Date().toISOString(),
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  } satisfies ITodoAppTodo.ICreate;
  const originalTodo = await generate_random_todo_app_member_todos_create(
    memberConnection,
    {
      body: createTodoBody,
    },
  );
  typia.assert(originalTodo);
  // Soft-delete todo (move to trash)
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId: originalTodo.id,
  });
  // Restore todo from trash
  const restoredTodo = await api.functional.todoApp.member.todos.trash.restore(
    memberConnection,
    {
      todoId: originalTodo.id,
    },
  );
  typia.assert(restoredTodo);
  // Validate that all original attributes are preserved
  TestValidator.equals(
    "todo ID should match",
    restoredTodo.id,
    originalTodo.id,
  );
  TestValidator.equals(
    "todo title should match",
    restoredTodo.title,
    originalTodo.title,
  );
  TestValidator.equals(
    "todo description should match",
    restoredTodo.description,
    originalTodo.description,
  );
  TestValidator.equals(
    "todo start_date should match",
    restoredTodo.start_date,
    originalTodo.start_date,
  );
  TestValidator.equals(
    "todo due_date should match",
    restoredTodo.due_date,
    originalTodo.due_date,
  );
  TestValidator.equals(
    "todo completed status should match",
    restoredTodo.completed,
    originalTodo.completed,
  );
  TestValidator.equals(
    "todo member should match",
    restoredTodo.member.id,
    originalTodo.member.id,
  );
  // Additional business logic validations
  TestValidator.predicate(
    "restored todo should have updated_at timestamp",
    restoredTodo.updated_at !== undefined,
  );
  TestValidator.predicate(
    "restored todo should have valid created_at timestamp",
    restoredTodo.created_at !== undefined,
  );
}

