    if (props.body.created_at.to) {
      // Convert ISO string to Date for Prisma query
      createdAtFilter.lte = new Date(props.body.created_at.to);
    }
    if (Object.keys(createdAtFilter).length > 0) {
      whereInput.created_at = createdAtFilter;
    }
