        : []),
      // Email filter
      ...(props.body.email ? [{ email: props.body.email }] : []),
      // Display name filter
      ...(props.body.display_name
        ? [
            props.body.display_name.length > 2
              ? {
                  display_name: {
                    // Trigram similarity - needs extension
                    contains: props.body.display_name,
